<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Algorithm Visualizer</title>
<style>
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    min-height: 100vh;
    background: #0d1117;
    color: #e6edf3;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 28px 16px 40px;
  }
  h1 {
    font-size: 20px;
    font-weight: 600;
    margin: 0 0 20px;
    letter-spacing: 0.4px;
  }
  #bars {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 3px;
    width: min(920px, 96vw);
    height: 480px;
    padding: 14px 12px;
    background: #161b22;
    border-radius: 12px;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
  }
  .bar {
    flex: 1 1 0;
    min-width: 2px;
    height: 0;
    background: linear-gradient(180deg, #79c0ff, #1f6feb);
    border-radius: 3px 3px 0 0;
    transition: height 0.12s ease, background 0.12s ease;
  }
  .controls {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    background: #21262d;
    color: #e6edf3;
    border: 1px solid rgba(255, 255, 255, 0.12);
    padding: 10px 22px;
    border-radius: 8px;
    font-size: 15px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
  }
  button:hover { background: #30363d; border-color: rgba(255, 255, 255, 0.22); }
  button:active { transform: translateY(1px); }
  #sort { background: #1f6feb; border-color: #1f6feb; }
  #sort:hover { background: #388bfd; }
</style>
</head>
<body>
  <h1>Sorting Algorithm Visualizer</h1>
  <div id="bars"></div>
  <div class="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>

<script>
(function () {
  var barsContainer = document.getElementById('bars');
  var data = [];
  // Bubble-sort progress state (step machine): si = outer index, sj = inner index.
  var si = 0, sj = 0;
  var sortTimer = null, sorting = false;

  function makeArray(n) {
    var a = new Array(n);
    for (var i = 0; i < n; i++) a[i] = Math.floor(Math.random() * 100) + 1;
    return a;
  }

  function swap(i, j) {
    var t = data[i]; data[i] = data[j]; data[j] = t;
  }

  function startSortState() { si = 0; sj = 0; }

  function isSorted() {
    for (var i = 1; i < data.length; i++) if (data[i] < data[i - 1]) return false;
    return true;
  }

  function render() {
    var max = 1;
    for (var i = 0; i < data.length; i++) if (data[i] > max) max = data[i];
    // Add bars as needed.
    while (barsContainer.children.length < data.length) {
      var b = document.createElement('div');
      b.className = 'bar';
      barsContainer.appendChild(b);
    }
    // Update heights of existing bars (reused -> smooth transitions).
    for (var k = 0; k < data.length; k++) {
      barsContainer.children[k].style.height = (data[k] / max * 100) + '%';
    }
    // Remove any leftover bars.
    while (barsContainer.children.length > data.length) {
      barsContainer.removeChild(barsContainer.lastChild);
    }
  }

  function stopSort() {
    if (sortTimer) { clearInterval(sortTimer); sortTimer = null; }
    sorting = false;
  }

  document.getElementById('sort').addEventListener('click', function () {
    if (sorting || isSorted()) return;
    sorting = true;
    startSortState();
    sortTimer = setInterval(function () {
      var done = window.viz.sortStep();
      if (done) stopSort();
    }, 40);
  });

  document.getElementById('shuffle').addEventListener('click', function () {
    stopSort();
    if (data.length === 0) data = makeArray(40);
    for (var i = data.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      swap(i, j);
    }
    startSortState();
    render();
  });

  document.getElementById('reset').addEventListener('click', function () {
    stopSort();
    data = makeArray(40);
    startSortState();
    render();
  });

  window.viz = {
    array: function () { return data.slice(); },

    setArray: function (a) {
      data = a.slice();
      startSortState();
      render();
    },

    // Advance the sort exactly one comparison/step. Returns true once sorted.
    sortStep: function () {
      var n = data.length;
      while (si < n - 1) {
        if (sj < n - 1 - si) {
          if (data[sj] > data[sj + 1]) swap(sj, sj + 1);
          sj++;
          render();
          return false;
        }
        si++;
        sj = 0;
      }
      render();
      return true;
    },

    sorted: function () { return isSorted(); }
  };

  // Initial state.
  data = makeArray(40);
  startSortState();
  render();
})();
</script>
</body>
</html>
